from pathlib import Path
import json,html,re,sys
sys.stdout.reconfigure(encoding='utf-8')
root=Path(__file__).resolve().parents[1]
d=json.loads((root/'data/presentation-preferences.json').read_text(encoding='utf-8'))
src={s['id']:s for s in d['sources']}
cat={c['id']:c['title'] for c in d['categories']}

templates=[(t['title'],t['prompt']) for t in d['templates']]

catalog=['# 발표 제작 요청 전체 목록','',d['coverage'],'',d['quote_policy'],'',f"정리일: {d['collected_on']}. 12개 분류, {len(d['rules'])}개 재사용 지침, {len(src)}개 출처 묶음. 아래 지침과 프롬프트는 원문을 일반화한 결과이며 구현 완료 증거가 아니다.",'','[핵심 원칙](presentation-style.md) · [복사용 프롬프트](presentation-prompt-pack.md) · [검색 화면](../prompt-library.html)']
for c in d['categories']:
    catalog+=['',f"## {c['title']}",'']
    for r in [x for x in d['rules'] if x['category']==c['id']]:
        catalog += [f"### {r['id']} {r['title']}",'',f"적용 범위: {r['scope']}",'',r['principle'],'',f"출처: {', '.join(r['sources'])}",'','재사용 프롬프트:','',f"> {r['prompt']}",'',f"확인 기준: {r['check']}"]
        if r['exception']:catalog+=['',f"예외와 주의: {r['exception']}"]
        if r['example']:catalog+=['',f"적용 예시: {r['example']}"]
        if r['legacy']:catalog+=['',f"기존 사례집 연결: {', '.join(r['legacy'])}"]
        catalog+=['']
catalog+=['## 요청 사이의 수정 관계','', '| 앞선 요청 | 후속 요청 | 관계 | 최종 해석 |','| --- | --- | --- | --- |']
for rel in d['relations']:catalog.append(f"| {rel['from_source']} | {rel['to_source']} | {rel['type']} | {rel['detail']} |")
catalog+=['','## 출처 원문 발췌','', '원문 발췌와 note의 요약을 구분한다. 메시지별 작성 일시가 확정되지 않은 항목은 날짜를 추정하지 않았다. 첨부 이미지의 글자를 새로 전사한 기록은 아니다.','']
for s in d['sources']:
    catalog += [f"### {s['id']} {s['title']}",'',f"{s['kind']} · {s['quotation']}",'','\n'.join('> '+x for x in s['quote'].splitlines())]
    if s['note']:catalog+=['',f"정리 메모: {s['note']}"]
    catalog+=['']
catalog+=['## 이번 사례에만 해당하는 제품 화면 세부값','',
 '다음은 일반 디자인 규칙이 아닌 AutoPets 기획 맥락이다. 새 발표에 복사할 때 제품과 사용자 상황에 맞춰 바꾼다.','',
 '- MVP의 4장: 펫 선택→설정→계획 확인→실행. 16:9, 같은 검은 고양이, 작은 MVP 콘셉트 표시, 오른쪽 위 내 펫/라이브러리로 돌아가는 집 버튼.',
 '- 선택 화면: 알뜰 너구리·꼼꼼 고양이·집중 호랑이, 고양이 선택 상태, 성향 한 줄·대표 스킬, 대상 채팅 학과 행사 웹페이지, 설정하기 버튼.',
 '- 설정 화면: 웹페이지 제작(요구사항 정리·화면 구현·결과 점검), 계획 Astra·추론 높음→실행 Luna·추론 보통, 계획을 확인한 뒤 실행, 저장하고 이 채팅에 부르기, 상세 모델 변경 입구. 성능 점수·절약률을 넣지 않는 설정 예시.',
 '- 계획 화면: 행사 소개·일정 구성, 신청 버튼이 있는 화면 제작, 모바일·동작 확인의 3단계. 수정하기/이 계획으로 시작 버튼. 실행 화면: 웹페이지 만드는 중, 실행 Luna, 계획 확인→화면 제작→결과 확인, 작업으로 돌아가기.',
 '- 역할 라이브러리: UI UX Pro Max 기반 UI 디자이너 고양이, Ponytail 기반 코드 정리 포니, 역할 템플릿인 리서처 부엉이·문서 편집자 토끼. 실제 스킬 설치·연동 완료 주장 없음.',
 '- 추천 대화: 어떤 결과를 만들고 싶어요?→웹페이지요. 어디부터 도움이 필요해요?→처음이라 잘 모르겠어요. UI 디자이너 추천→목적과 화면 구성부터 정리→누가 보는 페이지인지 확인.',
 '- 비교 의미: 모델은 몸 크기, 추론은 같은 크기에서 3칸 집중 게이지. 모델·추론·스킬 효과를 분리. MCP는 실제 브랜드 장난감, 관련 작업은 같은 종류의 역할별 펫·하네스, 꾸미기·진화는 확장 계획.',
 '- 개발 진행 표는 설치부터 배포 검증까지 15개 구간의 계획이다. 모든 항목이 구현됐다는 근거가 아니다.',
 '- 후반 학과 서사는 발표자의 자아 정의와 지향점이다. YouTube·Netflix·Adobe·Figma는 복잡한 기술을 쓰기 쉬운 도구로 설명하는 예시이며 일반적 우열이나 회사 탄생 원인의 확정 근거가 아니다.',
 '- 이번 수정 이력은 새 발표에 펫을 반드시 넣으라는 지시도, 기존 20장 구성·초록색을 그대로 써야 한다는 지시도 아니다.','']
(root/'references/presentation-request-catalog.md').write_text('\n'.join(catalog),encoding='utf-8')
pack=['# 상황별 발표 제작 프롬프트','', '대괄호를 내 발표에 맞게 바꾸고 필요한 문단만 복사한다. 이 문장들은 사용자 원문이 아니라 누적 요청에서 일반화한 재사용 문장이다. 현재 요청이 이 예시와 다르면 현재 요청이 우선한다.','']
for title,prompt in templates:pack += [f'## {title}','','```text',prompt,'```','']
pack+=['## 최소 사용 순서','','1. 새 발표 시작 프롬프트에 목적·시간·청중·자료를 채운다.','2. 표현을 고를 때 로고·전환·캐릭터 등 필요한 프롬프트만 추가한다.','3. 수정은 대상과 유지할 범위를 정해서 요청한다.','4. 최종 납품 때만 용량·오프라인·패키지 전체 검수를 적용한다.','','[전체 요청 기록](presentation-request-catalog.md) · [핵심 원칙](presentation-style.md)']
(root/'references/presentation-prompt-pack.md').write_text('\n'.join(pack),encoding='utf-8')

payload=json.dumps(d,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>발표 제작 프롬프트 라이브러리</title><style>
:root{color-scheme:light;--green:#276149;--ink:#19281f;--muted:#61756a;--line:#dae5dd}*{box-sizing:border-box}body{margin:0;background:#f6f8f5;color:var(--ink);font-family:Arial,"Malgun Gothic",sans-serif;line-height:1.7}button,input,select,textarea{font:inherit}button,a,input,select{touch-action:manipulation}button{cursor:pointer}a{color:var(--green)}header{padding:64px max(6vw,24px) 32px;background:white;border-bottom:1px solid var(--line)}header .eyebrow{font-size:12px;font-weight:700;color:var(--green);letter-spacing:2px}h1{font-size:clamp(28px,4vw,46px);letter-spacing:-2px;line-height:1.25;margin:14px 0}header p{max-width:770px;color:var(--muted);font-size:16px}header nav{display:flex;gap:20px;flex-wrap:wrap;font-size:14px}main{max-width:1380px;margin:auto;padding:28px max(3vw,20px) 64px}.controls{position:sticky;top:0;background:#f6f8f5f7;backdrop-filter:blur(12px);z-index:2;padding:14px 0;display:grid;grid-template-columns:1fr auto auto;gap:12px}input,select{min-width:0;padding:13px 16px;border:1px solid #bdcfc2;border-radius:10px;background:white;color:var(--ink)}input:focus,button:focus-visible,select:focus{outline:3px solid #97bfa8;outline-offset:3px}.tabs{display:flex;gap:8px;margin-bottom:10px}.tabs button{border:1px solid var(--line);background:white;border-radius:30px;padding:9px 18px;color:var(--muted)}.tabs button[aria-pressed=true]{background:var(--green);color:white;border-color:var(--green)}.count{color:var(--muted);font-size:14px;margin:12px 0 18px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{padding:24px;border:1px solid var(--line);border-radius:15px;background:white;display:flex;flex-direction:column;min-width:0}.tag{font-size:12px;color:var(--green);display:block}.card h2{font-size:20px;letter-spacing:-.65px;line-height:1.5;margin:8px 0 12px}.card p{font-size:14px;color:var(--muted);margin:0 0 18px}.card button{margin-top:auto;align-self:flex-start;border:0;background:#edf4ee;color:var(--green);border-radius:8px;padding:9px 15px;font-weight:700}.empty{padding:50px;color:var(--muted);grid-column:1/-1}dialog{max-width:900px;width:calc(100% - 32px);max-height:90vh;border:1px solid var(--line);border-radius:18px;padding:30px;color:var(--ink)}dialog::backdrop{background:#10251a70}dialog h2{font-size:28px;line-height:1.4;padding-right:40px;letter-spacing:-1px;margin-top:8px}dialog h3{font-size:16px;margin-top:26px}dialog p,dialog li{font-size:15px}.close{position:absolute;right:20px;top:17px;border:0;background:#f0f4ef;border-radius:50%;width:36px;height:36px;font-size:24px}textarea{display:block;width:100%;resize:vertical;border:1px solid #c5d8ca;border-radius:10px;background:#f4f8f2;padding:16px;line-height:1.8;color:#274b35;min-height:160px;font-size:15px}.copy{background:var(--green);color:white;border:0;border-radius:8px;padding:10px 18px;margin-top:12px}.copy-status{font-size:13px;color:var(--muted);margin-left:12px}.quotes{border-top:1px solid var(--line);margin-top:24px;padding-top:14px}.quote{background:#fafaf7;border-left:3px solid #bacfbf;padding:14px 18px;white-space:pre-wrap;font-size:14px}.note{font-size:13px!important;color:var(--muted)}details{margin-top:16px}summary{cursor:pointer;font-weight:700}.relation{padding:16px 20px;background:white;border:1px solid var(--line);border-radius:10px;margin-bottom:12px}.relation small{color:var(--green)}.relation p{margin:4px 0}.scope{font-size:12px;color:#637366;border-top:1px solid #edf0eb;padding-top:10px;margin:4px 0 15px}.principle{border-left:3px solid var(--green);padding-left:16px}.foot{margin-top:38px;font-size:12px;color:var(--muted)}@media(max-width:950px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.controls{grid-template-columns:1fr 1fr}.controls input{grid-column:1/-1}}@media(max-width:600px){header{padding-top:35px}.grid{grid-template-columns:1fr}.controls{position:static;grid-template-columns:1fr}.controls input{grid-column:auto}dialog{padding:22px}.tabs{flex-wrap:wrap}}
</style></head><body><header><div class="eyebrow">PROMPT LIBRARY · 2026.09.30</div><h1>내 발표 방식, 다음 PPT에도.</h1><p>로고 플레이부터 세부 문구 삭제, 장면 연결과 최종 용량 검수까지.<br>요청 원문은 보존하고, 다른 발표에 쓸 문장은 따로 정리했습니다.</p><nav><a href="references/presentation-style.md">핵심 제작 원칙</a><a href="references/presentation-prompt-pack.md">통합 프롬프트 모음</a><a href="references/presentation-request-catalog.md">전체 원문과 기록</a><a href="https://swaan-kim.github.io/html-pitch-artifacts-v2/">기존 화면 갤러리</a></nav></header><main><div class="tabs"><button data-tab="rules" aria-pressed="true">64개 제작 지침</button><button data-tab="templates" aria-pressed="false">16개 복사용 프롬프트</button><button data-tab="relations" aria-pressed="false">10개 수정 관계</button></div><div class="controls"><input id="search" type="search" placeholder="로고, 문구 삭제, 구르미, 용량…" aria-label="프롬프트 검색"><select id="category" aria-label="분류"><option value="">모든 분류</option></select><select id="scope" aria-label="적용 범위"><option value="">모든 적용 범위</option></select></div><div id="count" class="count" role="status" aria-live="polite"></div><div id="results" class="grid"></div><p class="foot">수집 범위는 이 대화와 기존 25건 사례집입니다. 원문은 발췌이며 반복 요청은 묶었습니다. 규칙과 일반화한 프롬프트는 원문과 구분합니다. 특정 프로젝트의 값과 새 발표의 요구가 다르면 새 요청을 우선합니다. 외부 서비스 연결 없이 검색·복사가 가능합니다.</p></main><dialog id="detail" aria-labelledby="detail-title"><button class="close" aria-label="닫기">×</button><div id="detail-body"></div></dialog><script id="library-data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('library-data').textContent),$=id=>document.getElementById(id),sourceMap=new Map(data.sources.map(s=>[s.id,s])),catMap=new Map(data.categories.map(c=>[c.id,c.title]));let tab='rules';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
data.categories.forEach(c=>$('category').add(new Option(c.title,c.id)));[...new Set(data.rules.map(r=>r.scope))].forEach(s=>$('scope').add(new Option(s,s)));
function render(){const q=$('search').value.trim().toLowerCase(),category=$('category').value,scope=$('scope').value;const items=data[tab].filter(r=>{const text=JSON.stringify(r)+(r.sources||[]).map(id=>JSON.stringify(sourceMap.get(id))).join('');return(!q||text.toLowerCase().includes(q))&&(tab!=='rules'||(!category||r.category===category)&&(!scope||r.scope===scope));});$('count').textContent=items.length+'개 결과 · '+(tab==='rules'?'항목을 열면 원문과 재사용 프롬프트가 함께 보입니다.':tab==='templates'?'필요한 문장만 골라 복사하세요.':'대체와 보완을 구분해 최신 상태를 적용합니다.');$('results').className=tab==='relations'?'':'grid';$('results').innerHTML=items.map(r=>tab==='relations'?`<div class="relation"><small>${esc(r.type)} · ${r.from_source} → ${r.to_source}</small><p>${esc(r.detail)}</p></div>`:`<article class="card"><span class="tag">${esc(tab==='rules'?catMap.get(r.category):r.id==='T01'?'START HERE':'COPY & ADAPT')} · ${r.id}</span><h2>${esc(r.title)}</h2><p>${esc(r.principle||r.prompt.slice(0,115)+'…')}</p>${r.scope?`<div class="scope">${esc(r.scope)}</div>`:''}<button data-open="${r.id}">${tab==='rules'?'원문과 재사용 문장':'프롬프트 열기'} →</button></article>`).join('')||'<p class="empty">검색 결과가 없습니다. 검색어나 분류를 바꿔보세요.</p>';}
function openItem(id){const r=[...data.rules,...data.templates].find(x=>x.id===id);const quotes=(r.sources||[]).map(id=>{const s=sourceMap.get(id);return `<details><summary>${id} ${esc(s.title)}</summary><p class="note">${esc(s.kind)} · ${esc(s.quotation)}</p><blockquote class="quote">${esc(s.quote)}</blockquote>${s.note?`<p class="note">정리 메모: ${esc(s.note)}</p>`:''}</details>`}).join('');$('detail-body').innerHTML=`<span class="tag">${r.id} · ${esc(r.scope||'복사용 일반화 프롬프트')}</span><h2 id="detail-title">${esc(r.title)}</h2>${r.principle?`<p class="principle">${esc(r.principle)}</p>`:''}<h3>재사용 프롬프트</h3><textarea id="prompt-text" readonly aria-label="복사할 프롬프트">${esc(r.prompt)}</textarea><button class="copy" data-copy="prompt-text">프롬프트 복사</button><span class="copy-status" id="copy-status" role="status"></span>${r.check?`<h3>확인 기준</h3><p>${esc(r.check)}</p>`:''}${r.exception?`<h3>예외와 적용 범위</h3><p>${esc(r.exception)}</p>`:''}${r.example?`<h3>AutoPets에서의 예시</h3><p>${esc(r.example)}</p>`:''}${quotes?`<div class="quotes"><h3>사용자 원문 발췌</h3><p class="note">위 프롬프트는 일반화한 문장입니다. 아래 원문과 구분해서 사용하세요.</p>${quotes}</div>`:''}`;$('detail').showModal();$('prompt-text').style.height=Math.min(480,Math.max(160,$('prompt-text').scrollHeight+4))+'px';}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('category').disabled=$('scope').disabled=tab!=='rules';render();}));['search','category','scope'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));$('results').addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)openItem(b.dataset.open);});$('detail').querySelector('.close').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('click',async e=>{if(e.target!==$('detail')&&!e.target.closest('[data-copy]'))return;if(e.target===$('detail')){$('detail').close();return;}const field=$('prompt-text');try{if(!navigator.clipboard?.writeText)throw new Error('fallback');await navigator.clipboard.writeText(field.value);$('copy-status').textContent='복사했습니다.';}catch{field.focus();field.select();$('copy-status').textContent='텍스트가 선택되었습니다. Ctrl+C 또는 ⌘C로 복사하세요.';}});render();
</script></body></html>'''
(root/'prompt-library.html').write_text(page.replace('__DATA__',payload).replace('64개 제작 지침',str(len(d['rules']))+'개 제작 지침').replace('16개 복사용 프롬프트',str(len(templates))+'개 복사용 프롬프트').replace('10개 수정 관계',str(len(d['relations']))+'개 수정 관계'),encoding='utf-8')
print(json.dumps({'rules':len(d['rules']),'sources':len(d['sources']),'templates':len(templates),'html_KiB':round((root/'prompt-library.html').stat().st_size/1024,1)},ensure_ascii=False))
